import{_ as t,o as n,c as a,ak as o}from"./chunks/framework.B8jO0odJ.js";const m=JSON.parse('{"title":"Chainy documentation: start here","description":"Read the five essentials in order, then open only the supporting reference needed for your role.\\nFor Obsidian topic maps and graph navigation, use Home.\\nCurrent work is docume","frontmatter":{"title":"Chainy documentation: start here","description":"Read the five essentials in order, then open only the supporting reference needed for your role.\\nFor Obsidian topic maps and graph navigation, use Home.\\nCurrent work is docume","source":"docs/documentation-index.md","category":"Start here","sourceUpdated":"2026-11-11T12:24:37+08:00","outline":[2,3]},"headers":[],"relativePath":"content/docs/documentation-index.md","filePath":"content/docs/documentation-index.md"}'),r={name:"content/docs/documentation-index.md"};function s(i,e,d,c,h,l){return n(),a("div",null,[...e[0]||(e[0]=[o('<div><h1 id="chainy-documentation-start-here">Chainy documentation: start here<a class="header-anchor" href="#chainy-documentation-start-here" aria-label="Link to this section">​</a></h1><p>Read the five essentials in order, then open only the supporting reference needed for your role. For Obsidian topic maps and graph navigation, use <a href="/Chainy-Docs/content/docs/home.html">Home</a>. <strong>Current work is documentation and necessary preparation; Unity development requires final owner approval.</strong></p><h2 id="five-essentials">Five essentials<a class="header-anchor" href="#five-essentials" aria-label="Link to this section">​</a></h2><table><thead><tr><th>Question</th><th>Source of record</th></tr></thead><tbody><tr><td>How does the game play?</td><td><a href="/Chainy-Docs/content/docs/game-design-lesson-collection.html">Lesson-collection GDD</a></td></tr><tr><td>What does it teach?</td><td><a href="/Chainy-Docs/content/docs/planning/a-z-complete-lesson-quiz-source-draft.html">A–Z and AI lesson source pack</a></td></tr><tr><td>What is decided?</td><td><a href="/Chainy-Docs/content/docs/project-baseline.html">Current baseline</a></td></tr><tr><td>What must be ready before development?</td><td><a href="/Chainy-Docs/content/docs/planning/lesson-collection-delivery.html">Readiness and future parallel workflow</a></td></tr><tr><td>How will it be checked?</td><td><a href="/Chainy-Docs/content/docs/qa-evaluation.html">QA and evaluation</a></td></tr></tbody></table><p>Current scope is 39 ordered lessons, nine distinct minigames and three sequential worlds: Web3 → Blockchain → AI. Each world requires its 13-question review, one question per lesson, with incorrect answers retried until all are correct. AI uses labeled offline simulations. An economy system, teacher services, exports and standalone Wordle/BlockMatch are outside current scope.</p><h2 id="start-by-responsibility">Start by responsibility<a class="header-anchor" href="#start-by-responsibility" aria-label="Link to this section">​</a></h2><table><thead><tr><th>Owner</th><th>Supporting references</th></tr></thead><tbody><tr><td>Sherwin: coordination and design</td><td><a href="/Chainy-Docs/content/docs/project-baseline.html">Decisions</a>, <a href="/Chainy-Docs/content/docs/kanban-plan-draft.html">current task plan</a>, <a href="/Chainy-Docs/content/docs/manuscript-evidence-map.html">school evidence gaps</a></td></tr><tr><td>Christian: code, data, builds and integration</td><td><a href="/Chainy-Docs/content/docs/technical-design.html">Technical design</a>, <a href="/Chainy-Docs/content/docs/design/database-schema.html">database contract</a>, <a href="/Chainy-Docs/content/docs/hardware-validation.html">device checks</a>, <a href="/Chainy-Docs/content/docs/requirements/technical-requirements.html">technical acceptance</a></td></tr><tr><td>Luis: art assets</td><td><a href="/Chainy-Docs/content/docs/design/design-brief.html">Art and UI brief</a>, <a href="/Chainy-Docs/content/docs/game-design-lesson-collection.html#7-complete-lesson-route">current lesson route</a></td></tr><tr><td>Sean: all authored documentation</td><td><a href="/Chainy-Docs/content/docs/manuscript-evidence-map.html">Manuscript evidence map</a>, <a href="/Chainy-Docs/content/docs/manuscript-working-draft.html">working draft</a>, <a href="/Chainy-Docs/content/docs/user-guide.html">learner guide</a>, <a href="/Chainy-Docs/content/docs/learning-foundations.html">learning foundations</a></td></tr><tr><td>Miguel: game UI implementation</td><td><a href="/Chainy-Docs/content/docs/design/app-flow.html">Player flow</a>, <a href="/Chainy-Docs/content/docs/design/design-brief.html">art and UI brief</a></td></tr></tbody></table><p>The GDD owns gameplay rules; supporting documents describe their respective contracts and evidence needs. Use <a href="/Chainy-Docs/content/docs/requirements/product-requirements.html">product acceptance</a> for the acceptance map and <a href="/Chainy-Docs/content/docs/offline-data-plan.html">offline records</a> for local-data boundaries. Draft content, static source observations and runtime results have different meanings.</p><h2 id="tasks-evidence-and-history">Tasks, evidence and history<a class="header-anchor" href="#tasks-evidence-and-history" aria-label="Link to this section">​</a></h2><p>Edit task status, dates and named handoffs through the <a href="https://owenlim225.github.io/Chainy-Docs/board/">team board</a>. See the <a href="/Chainy-Docs/content/docs/team-board-guide.html">board guide</a> and <a href="/Chainy-Docs/content/docs/team-delegation.html">one-owner role lanes</a>. GitHub issues are queued copies; <a href="/Chainy-Docs/attachments/docs/backlog.json">backlog.json</a> is the publication snapshot. Rebaseline unfinished work after documentation review while preserving prior work and history.</p><p><strong>Pre-final remains November 21, 2026.</strong> The November 10 session&#39;s actual outcome and unresolved school requirements need evidence. Protect integration, device QA, manuscript and rehearsal time without treating the calendar as proof of feasibility.</p><p>Earlier proposals and original sources are grouped under <a href="/Chainy-Docs/content/docs/brain/07-sources.html">07 Sources and history</a> and the <a href="/Chainy-Docs/content/docs/archive/readme.html">archive</a>. They do not create additional current requirements.</p></div>',1)])])}const p=t(r,[["render",s]]);export{m as __pageData,p as default};
